using cl2j.Database.CommandBuilders;

namespace cl2j.Database.MySql
{
    /// <summary>
    ///     Entry point of the MySQL provider.
    /// </summary>
    public static class MySql
    {
        /// <summary>
        ///     Registers the MySQL command builder, so that every <c>MySqlConnection</c> the library
        ///     is given is served by it. Call once at start-up, before the first operation.
        /// </summary>
        /// <param name="identifierGenerator">
        ///     Generates the value of an <c>AutoGeneratedKey</c> column. <c>null</c> keeps the default
        ///     (a new <see cref="Guid"/>).
        /// </param>
        public static void Register(IIdentifierGenerator? identifierGenerator = null)
        {
            CommandBuilderFactory.Register(new MySqlCommandBuilder(identifierGenerator));
        }
    }
}
